//! Differential fuzz test for `ansi.rs` against ground truth generated by
//! running the ORIGINAL `dist/utils/ansi.js` under Node (see PARITY.md).
//! The corpus lives in `tests/data/ansi-fuzz.json`; the test is skipped
//! when the file is absent.

use pi_core::ansi::{split_incomplete_ansi_suffix, strip_ansi};
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    input: String,
    strip: String,
    split: Split,
}

#[derive(Deserialize)]
struct Split {
    complete: String,
    pending: String,
}

#[test]
fn ansi_fuzz_ground_truth() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/ansi-fuzz.json");
    let Ok(data) = std::fs::read_to_string(path) else {
        eprintln!("skipping: {} not found", path);
        return;
    };
    let cases: Vec<Case> = serde_json::from_str(&data).expect("valid corpus");
    assert!(cases.len() > 300, "corpus too small");
    let mut mismatches = 0;
    for case in &cases {
        let stripped = strip_ansi(&case.input);
        if stripped != case.strip {
            mismatches += 1;
            eprintln!(
                "strip_ansi mismatch: input={:?} got={:?} want={:?}",
                case.input, stripped, case.strip
            );
        }
        let (complete, pending) = split_incomplete_ansi_suffix(&case.input);
        if complete != case.split.complete || pending != case.split.pending {
            mismatches += 1;
            eprintln!(
                "split mismatch: input={:?} got=({:?},{:?}) want=({:?},{:?})",
                case.input, complete, pending, case.split.complete, case.split.pending
            );
        }
    }
    assert_eq!(mismatches, 0, "{} mismatches", mismatches);
}
